//! Frozen constructors and read-only observations; actual production Composer painter.
#[cfg(any(target_os="linux",target_os="windows"))]mod native{
use ingetrazo_gui::{app::IngeTrazoApp,native_vulkan::{App,System}};
use ingetrazo_core::composition::{Sheet,PaperSize,Orientation};
struct Fixture{app:IngeTrazoApp,index:usize,out:std::path::PathBuf,stats:serde_json::Value,serial:u64,recipes:Vec<serde_json::Value>}
impl Fixture{fn set_case(&mut self){let recipe=&self.recipes[self.index];let s=&mut self.app.scene.sheets[0];s.items.clear();s.native_items.clear();s.set_source_border(serde_json::from_value(recipe["border"].clone()).unwrap()).unwrap();for t in recipe["texts"].as_array().unwrap(){let item=ingetrazo_core::composition::TextItem{id:uuid::Uuid::new_v4(),pos:(t["x_mm"].as_f64().unwrap(),t["y_mm"].as_f64().unwrap()),text:t["text"].as_str().unwrap().into(),font_size_pt:t["size_pt"].as_f64().unwrap(),bold:t["bold"].as_bool().unwrap()};s.native_items.insert(item.id,t.clone());s.items.push(ingetrazo_core::composition::SheetItem::Text(item));}self.app.composer_state.zoom=recipe["zoom"].as_f64().unwrap() as f32;self.app.model_revision=self.app.model_revision.wrapping_add(1);}}

impl App for Fixture{
fn title()->&'static str{"IngeTrazo actual Composer paper compound acceptance"}
fn new(system:&mut System,_:Option<std::path::PathBuf>)->Self{let mut app=IngeTrazoApp::new();app.set_language("en");app.native_composer.factory=Some(system.enable_cad2d().unwrap().factory().into());let mut sheet=Sheet::new("Paper",PaperSize::A4,Orientation::Landscape);sheet.items.clear();sheet.margin_mm=10.;app.scene.sheets=vec![sheet];app.scene.active_sheet_index=Some(0);let recipes:serde_json::Value=serde_json::from_slice(&std::fs::read(std::env::var("INGETRAZO_AUTHORED_RECIPES").unwrap()).unwrap()).unwrap();assert_eq!(recipes["cases"].as_array().unwrap().len(),3);let mut out=Self{app,index:0,recipes:recipes["cases"].as_array().unwrap().clone(),out:std::env::var("INGETRAZO_BORDER_OUT").unwrap().into(),stats:serde_json::Value::Null,serial:0};out.set_case();out}
fn prepare_gpu(&mut self,system:&mut System,_:bool){let s=system.enable_cad2d().unwrap().stats();self.stats=serde_json::json!({"uploads":s.uploads,"cache_hits":s.cache_hits,"cached_bytes":s.cached_bytes,"draws":s.draws});self.serial=system.submitted_frames_for_probe();}
fn build_ui(&mut self,ctx:&egui::Context){let(mut next,mut close)=(egui::Pos2::ZERO,egui::Pos2::ZERO);egui::TopBottomPanel::top("controls").show(ctx,|ui|{ui.horizontal(|ui|{let b=ui.button("Next frozen compound");next=b.rect.center();if b.clicked(){self.index=(self.index+1)%3;self.set_case();}let b=ui.button("Finish");close=b.rect.center();if b.clicked(){ctx.send_viewport_cmd(egui::ViewportCommand::Close);}});});egui::CentralPanel::default().show(ctx,|ui|ingetrazo_gui::composer::render_sheet_composer(&mut self.app,ui,0));
if let Some(t)=ctx.data(|d|d.get_temp::<[f32;3]>(egui::Id::new("pdf-ui-paper-transform"))){let s=&self.app.scene.sheets[0];let state=serde_json::json!({"index":self.index,"name":self.recipes[self.index]["name"],"origin":[f64::from(t[0]),f64::from(t[1])],"zoom":f64::from(t[2]),"ppp":f64::from(ctx.pixels_per_point()),"page":s.dimensions_mm(),"margin":s.margin_mm,"border":s.effective_source_border(),"texts":self.recipes[self.index]["texts"],"canvas_paint_stats":ctx.data(|d|d.get_temp::<[u64;5]>(egui::Id::new("pdf-ui-canvas-paint-stats"))),"raw_texture_stats":ctx.data(|d|d.get_temp::<[u64;5]>(egui::Id::new("pdf-ui-raw-texture-stats"))),"cold_builds":ctx.data(|d|d.get_temp::<[u64;2]>(egui::Id::new("paper-cold-builds"))),"gpu":self.stats,"serial":self.serial,"status":self.app.status_message,"next":[next.x,next.y],"close":[close.x,close.y]});std::fs::write(self.out.join("state.tmp"),state.to_string()).unwrap();std::fs::rename(self.out.join("state.tmp"),self.out.join("state.json")).unwrap();}ctx.request_repaint_after(std::time::Duration::from_millis(30));}
fn gpu_error(&mut self,e:&str){panic!("Actual Composer paper GPU failure: {e}");}
}pub fn run()->Result<(),Box<dyn std::error::Error>>{ingetrazo_gui::native_vulkan::run_app::<Fixture>(None)}
}
#[cfg(any(target_os="linux",target_os="windows"))]fn main()->Result<(),Box<dyn std::error::Error>>{native::run()}
#[cfg(not(any(target_os="linux",target_os="windows")))]fn main(){eprintln!("Actual native paper probe requires Vulkan host");}
